import{_ as t,o as s,c as n,a2 as o}from"./chunks/framework.BXzK3EA4.js";const a="/assets/ba288b549a03f86e.DPtHFqV0.png",d="/assets/a291c65e28ef656b.3KO6Tx11.png",i="/assets/aecfc4f8a8f14f1f.Ckh-5BPY.png",r="/assets/358d2ea50d1f65ac.CrwrMnXD.png",p="/assets/06eadcbb01e99364.BsldCZlW.png",b=JSON.parse('{"title":"Add an IP address in Windows System","description":"","frontmatter":{"title":"Add an IP address in Windows System"},"headers":[],"relativePath":"operations-knowledge-base/operating-system/windows/add-an-ip-address-in-windows-system.md","filePath":"operations-knowledge-base/operating-system/windows/add-an-ip-address-in-windows-system.md","lastUpdated":1794309341000}'),c={name:"operations-knowledge-base/operating-system/windows/add-an-ip-address-in-windows-system.md"};function m(l,e,h,g,_,u){return s(),n("div",null,[...e[0]||(e[0]=[o('<p>Method 1: You can use the scripts provided in the <a href="/operations-knowledge-base/operating-system/">system tools</a> document to configure the commands directly.</p><p>Adding IP addresses consecutively.</p><p><img src="'+a+'" alt=""></p><p>Adding a block of IP addresses.</p><p><img src="'+d+'" alt=""></p><p>Method 2:</p><p>If the number of IP addresses to be added is small, you can also add them in the Advanced settings of IPv4 in Network Connections.</p><p><img src="'+i+'" alt=""></p><p><img src="'+r+'" alt=""></p><p><img src="'+p+'" alt=""></p><p>Method 3:</p><p>To batch add IP addresses using the command prompt:</p><p>Enter the command: <code>for /l %i in (starting\\_number,1,ending\\_number) do netsh interface ip add address &quot;Local Connection&quot; IP\\_prefix.%i subnet\\_mask</code></p><p>(Where starting_number and ending_number are the last digits of the IP address provided by the supplier, &quot;Local Connection&quot; is the network interface name, which may vary for each server and can be found in the Properties of Network Neighborhood.)</p><p>Open the command prompt by going to Start -&gt; Run -&gt; type &quot;cmd&quot; -&gt; Enter.</p><p>For example, available IP addresses: 174.139.111.82-174.139.111.86 (total of 5 available IPs)</p><p>Subnet mask: 255.255.255.248</p><p>Current network interface name: Local Connection 1</p><p>Then enter the command: <code>for /l %i in (82,1,86) do netsh interface ip add address &quot;Local Connection&quot; 174.139.111.%i 255.255.255.248</code></p><p>(You can copy the above command by right-clicking on your local computer, and then paste it directly into the command prompt window. This will help avoid typing errors and save time.)</p><p>Press Enter to execute the command. The IP addresses will be automatically added one by one.</p>',21)])])}const w=t(c,[["render",m]]);export{b as __pageData,w as default};
